<?php
if(!defined('ABSPATH')){exit;}
final class AICS_Native_SEO_Application_Service{
	public function __construct(private ?AICS_Article_Repository $articles=null){$this->articles=$articles??new AICS_Article_Repository();}
	public function apply(array $a,array $settings,int $user):array{$post_id=absint($a['wordpress_post_id']??0);$post=$post_id?get_post($post_id):null;if(!$post){return $this->fail('seo_post_not_found');}$source=sanitize_key((string)($a['source_type']??''));if(!in_array($source,array('manual','automation'),true)||$source!==(string)get_post_meta($post_id,'_aics_source',true)||absint($a['id'])!==absint(get_post_meta($post_id,'_aics_article_id',true))||(string)$a['article_uuid']!==sanitize_text_field((string)get_post_meta($post_id,'_aics_article_uuid',true))||('manual'===$source&&!user_can($user,'edit_post',$post_id))){return $this->fail('seo_post_ownership_invalid');}if(''===trim((string)$a['seo_focus_keyword'])||''===trim((string)$a['seo_slug'])){return $this->fail('seo_data_incomplete');}$current=hash('sha256',(string)$post->post_content);$managed=(string)get_post_meta($post_id,'_aics_managed_content_hash',true);if((''!==$managed&&!hash_equals($managed,$current))||(''===$managed&&(string)$post->post_content!==(string)$a['content'])){return $this->fail('seo_post_content_conflict');}
		$internal=(new AICS_Internal_Link_Recommendation_Service())->recommend($a,(new AICS_Internal_Link_Candidate_Service())->discover($a),!empty($settings['links']['internal_enabled'])?absint($settings['links']['internal_maximum']):0);$external=(new AICS_External_Link_Recommendation_Service())->recommend($a,$settings,!empty($settings['links']['external_enabled'])?absint($settings['links']['external_maximum']):0);$links=new AICS_SEO_Link_Insertion_Service();$ir=$links->insert((string)$a['content'],$internal,'internal');$er=$links->insert($ir['content'],$external,'external');$alt=substr(sanitize_text_field((string)($a['featured_image_alt_text']?:__('Descriptive featured image','ai-content-studio'))),0,250);$image=(new AICS_Content_Image_Insertion_Service())->insert($er['content'],$a,$settings,$alt);if(empty($image['success'])&&!in_array($image['code']??'',array('content_image_attachment_missing','content_image_disabled'),true)){return $this->fail('seo_content_image_insertion_failed');}$final=wp_kses_post(!empty($image['success'])?$image['content']:$er['content']);if(''===trim(wp_strip_all_tags($final))){return $this->fail('seo_native_application_failed');}$terms=$this->terms($a);if(is_wp_error($terms)){return $this->fail('seo_term_creation_failed');}$updated=wp_update_post(array('ID'=>$post_id,'post_name'=>sanitize_title((string)$a['seo_slug']),'post_excerpt'=>sanitize_textarea_field((string)$a['excerpt']),'post_content'=>$final),true);if(is_wp_error($updated)||absint($updated)!==$post_id){return $this->fail('seo_native_application_failed');}foreach($terms as $tax=>$ids){if($ids&&is_wp_error(wp_set_post_terms($post_id,$ids,$tax,true))){return $this->fail('seo_term_creation_failed');}}$attachment=absint($a['featured_image_attachment_id']??0);if($attachment){update_post_meta($attachment,'_wp_attachment_image_alt',$alt);}
		$data=new AICS_SEO_Data(array('focus_keyword'=>$a['seo_focus_keyword'],'seo_title'=>$a['seo_title'],'meta_description'=>$a['seo_meta_description'],'slug'=>$a['seo_slug'],'excerpt'=>$a['excerpt'],'categories'=>$a['seo_categories'],'tags'=>$a['seo_tags'],'internal_links'=>$ir['records'],'external_links'=>$er['records'],'image_alt_text'=>$alt));$next=$a;$next['content']=$final;$analysis=(new AICS_SEO_Quality_Analyzer())->analyze($data,$next,$settings,(string)($a['seo_target_plugin']?:'native'));$hash=hash('sha256',$final);update_post_meta($post_id,'_aics_managed_content_hash',$hash);update_post_meta($post_id,'_aics_last_seo_application_hash',$hash);update_post_meta($post_id,'_aics_seo_applied','1');if(!empty($image['attachment_id'])){update_post_meta($post_id,'_aics_content_image_attachment_id',absint($image['attachment_id']));}return array('success'=>true,'code'=>$current===$hash?'seo_application_already_current':'seo_application_succeeded','post_id'=>$post_id,'content'=>$final,'data'=>$data,'internal_links'=>$ir['records'],'external_links'=>$er['records'],'image'=>$image,'analysis'=>$analysis,'alt'=>$alt,'native_applied'=>true);}
	private function terms(array $a){$out=array('category'=>array(),'post_tag'=>array());foreach(array('category'=>'seo_categories','post_tag'=>'seo_tags') as $tax=>$field){foreach(array_slice(is_array($a[$field]??null)?$a[$field]:array(),0,'category'===$tax?5:15) as $name){$name=substr(sanitize_text_field((string)$name),0,100);if(''===$name){continue;}$term=get_term_by('name',$name,$tax)?:get_term_by('slug',sanitize_title($name),$tax);if(!$term){$term=wp_insert_term($name,$tax);if(is_wp_error($term)){return $term;}$out[$tax][]=absint($term['term_id']);}else{$out[$tax][]=absint($term->term_id);}}$out[$tax]=array_values(array_unique($out[$tax]));}return $out;}private function fail(string $code):array{return array('success'=>false,'code'=>$code,'retryable'=>in_array($code,array('seo_native_application_failed','seo_term_creation_failed','seo_plugin_refresh_failed'),true));}
}
